return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ckb','project-id-version'=>'babilim-0.1.0-ckb-babilim-0.1.0-ckb-20261030T020808','pot-creation-date'=>'2026-10-30T06:25:12+00:00','po-revision-date'=>'2026-10-30T06:25:12+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'وەرگێڕانە ونبووەکانی ئەو پێوەکراو و ڕووکارانە پڕ دەکاتەوە کە پێشتر لەسەر ماڵپەڕەکەت دامەزراون.','Translations'=>'وەرگێڕانەکان','Babilim Settings'=>'ڕێکخستنەکانی Babilim','Settings'=>'ڕێکخستنەکان','You are not allowed to do this.'=>'ڕێگەپێدراو نیت ئەم کارە بکەیت.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'پێکهاتەی کەمتر هەڵبژێرە: لە هەر جارێکدا زیاترین %1$d کردار (تۆ %2$d هەڵبژاردووە).','That component is not installed on this site, so a translation cannot be requested for it.'=>'ئەم پێکهاتەیە لەسەر ئەم ماڵپەڕە دانەمەزراوە، بۆیە ناتوانرێت وەرگێڕان بۆی داوا بکرێت.','Already installed.'=>'پێشتر دامەزراوە.','Downloaded and installed.'=>'داگیرا و دامەزرا.','Babilim has not been enabled for this site yet.'=>'Babilim هێشتا بۆ ئەم ماڵپەڕە چالاک نەکراوە.','No build is available to download for this locale.'=>'هیچ بیلدێک بۆ داگرتن بۆ ئەم ناوچەی زمانە بەردەست نییە.','Rolled back to the previous build.'=>'گەڕایەوە بۆ بیلدی پێشوو.','Rolled back and reported.'=>'گەڕایەوە و ڕاپۆرت کرا.','Rolled back, but the report could not be sent: %s'=>'گەڕایەوە، بەڵام ڕاپۆرتەکە نەتوانرا بنێردرێت: %s','Removed.'=>'لابرا.','Translation requested.'=>'وەرگێڕان داوا کرا.','This component was already uploaded. Babilim is checking it now.'=>'ئەم پێکهاتەیە پێشتر بارکراوە. Babilim ئێستا دەیپشکنێت.','Upload cancelled.'=>'بارکردن هەڵوەشێنرایەوە.','Upload complete — translation requested.'=>'بارکردن تەواو بوو — وەرگێڕان داوا کرا.','This component does not declare a version number, so a translation cannot be requested for it.'=>'ئەم پێکهاتەیە ژمارەی وەشان ڕاناگەیەنێت، بۆیە ناتوانرێت وەرگێڕان بۆی داوا بکرێت.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'ژمارەی وەشانی ئەم پێکهاتەیە لە %d پیت درێژترە، کە Babilim ناتوانێت مامەڵەی لەگەڵ بکات، بۆیە ناتوانرێت وەرگێڕان بۆی داوا بکرێت.','A translation cannot be requested for that locale on this site right now.'=>'ئێستا ناتوانرێت وەرگێڕان بۆ ئەو ناوچەی زمانە لەسەر ئەم ماڵپەڕە داوا بکرێت.','Thank you. Your report was sent.'=>'سوپاس. ڕاپۆرتەکەت نێردرا.','This report does not name a valid plugin or theme and locale.'=>'ئەم ڕاپۆرتە پێوەکراو یان ڕووکارێکی دروست و ناوچەی زمانێکی دروست دیاری ناکات.','Please choose a category for this report.'=>'تکایە هاوپۆلێک بۆ ئەم ڕاپۆرتە هەڵبژێرە.','This report is missing a valid build to report against.'=>'ئەم ڕاپۆرتە بیلدێکی دروستی نییە بۆ ئەوەی ڕاپۆرتی لەسەر بکرێت.','This build is not one this site currently knows about for this component/locale.'=>'ئەم بیلدە ئەو بیلدە نییە کە ئەم ماڵپەڕە ئێستا بۆ ئەم پێکهاتە/ناوچەی زمانە دەیناسێت.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'خانەی "%1$s" زۆر درێژە: %2$d پیتی هەیە و سنوورەکە %3$dـە. هیچ نەنێردرا؛ تکایە کورتی بکەرەوە و دووبارە هەوڵبدەرەوە.','Original string'=>'دەقی ڕەسەن','String context'=>'گوتەی دەقەکە','Current translation'=>'وەرگێڕانی ئێستا','Suggested translation'=>'وەرگێڕانی پێشنیارکراو','Note (optional)'=>'تێبینی (دڵخوازانە)','Where you saw this (optional)'=>'لە کوێ ئەمەت بینی (دڵخوازانە)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'هاوکاتکردنی Babilim بە شێوەیەکی کاتی لەلایەن خزمەتگوزارییەکەوە دواخراوە (سنووردارکردنی ڕێژە)؛ دوای %s دووبارە هەوڵ دەداتەوە.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'ناوچەی زمانی زیادکراو دروست نییە: کۆدی ناوچەی زمانی WordPress وەک ll_CC بەکاربهێنە (پیت، ژمارە، هێڵی ژێرەوە، هێڵی پەیوەندی (-) یان @، بە زۆرترین %d کارەکتەر). هیچ پاشەکەوت نەکرا.','Settings saved.'=>'ڕێکخستنەکان پاشەکەوت کران.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'ئەگەر ئەمە چالاک بێت، لابردن ناسنامەی ئەم ماڵپەڕەش دەسڕێتەوە. مۆڵەتی پارەدراوی بەستراو بەم ماڵپەڕەوە دواتر بە شێوەی خۆکار ناگەڕێندرێتەوە؛ دەبێت بۆ گەڕاندنەوەی پەیوەندی بە پشتگیری Babilim بکەیت لە %s.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim ڕێک خراوە کاتێک پێوەکراوەکە دەسڕدرێتەوە ناسنامەی ئەم ماڵپەڕە بسڕێتەوە. مۆڵەتی پارەدراوی بەستراو بەم ماڵپەڕەوە دواتر بە شێوەی خۆکار ناگەڕێندرێتەوە؛ دەبێت پەیوەندی بە پشتگیری Babilim بکەیت لە %s. بۆ هێشتنەوەی ناسنامە، دوگمەی پاشگەزبوونەوە دابگرە، تیکی "سڕینەوەی هەموو داتاکانی Babilim لەکاتی لابردن" لە ڕێکخستنەکانی Babilim لاببە، و دووبارە ناچالاکی بکە. سەرەڕای ئەوەش ناچالاک بکرێت؟','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d ماڵپەڕ لەسەر ئەم تۆڕە ڕێک خراوە کاتێک پێوەکراوەکە دەسڕدرێتەوە ناسنامەی Babilim بسڕێتەوە. مۆڵەتی پارەدراوی بەستراو بەو ماڵپەڕەوە دواتر بە شێوەی خۆکار ناگەڕێندرێتەوە؛ دەبێت پەیوەندی بە پشتگیری Babilim بکەیت لە %2$s. بۆ هێشتنەوەی ناسنامە، Cancel دابگرە، تیکی "سڕینەوەی هەموو داتاکانی Babilim لەکاتی لابردن" لە ڕێکخستنەکانی Babilim ی ئەو ماڵپەڕە لاببە، و دووبارە ناچالاکی بکە. ئایا بەهەر حاڵ ناچالاک بکرێت؟' . "\0" . '%1$d ماڵپەڕ لەسەر ئەم تۆڕە ڕێک خراون کاتێک پێوەکراوەکە دەسڕدرێتەوە ناسنامەی Babilim یان بسڕێتەوە. مۆڵەتی پارەدراوی بەستراو بەو ماڵپەڕانەوە دواتر بە شێوەی خۆکار ناگەڕێندرێتەوە؛ دەبێت پەیوەندی بە پشتگیری Babilim بکەیت لە %2$s. بۆ هێشتنەوەی ناسنامەکان، Cancel دابگرە، تیکی "سڕینەوەی هەموو داتاکانی Babilim لەکاتی لابردن" لە ڕێکخستنەکانی Babilim ی هەر ماڵپەڕێک لاببە، و دووبارە ناچالاکی بکە. ئایا بەهەر حاڵ ناچالاک بکرێت؟','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'ئەم تۆڕە ماڵپەڕی زۆری تێدایە بۆ ئەوەی یەک بە یەک بپشکنرێن، و ڕەنگە هەندێکیان ڕێکخرابن بۆ ئەوەی ناسنامەی Babilim یان بسڕدرێتەوە کاتێک پێوەکە دەسڕدرێتەوە. مۆڵەتی پارەدراوی بەستراو بەو ماڵپەڕانە دواتر ناتوانرێت بە خۆکار بگەڕێندرێتەوە؛ دەبێت پەیوەندی بە پشتگیری Babilim بکەیت لە %s. بۆ پاراستنی ناسنامەکان، دوگمەی پاشگەزبوونەوە دابگرە، نیشانەی "سڕینەوەی هەموو داتاکانی Babilim لەکاتی لابردن" لە ڕێکخستنەکانی Babilim ی هەر ماڵپەڕێک لابەرە، و دووبارە ناچالاکی بکە. هەر بەو شێوەیە ناچالاک بکرێت؟','Open Babilim settings'=>'کردنەوەی ڕێکخستنەکانی Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim نەیتوانی ئەم ماڵپەڕە پشتڕاست بکاتەوە، بۆیە هیچ داونلۆد یان دامەزراندن ناکرێت.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'خزمەتگوزارییەکە نەیتوانی بگاتە ماڵپەڕەکەت. ڕەنگە دیواری ئاگر، پێوەی ئاسایش یان ڕێسایەکی هۆست داواکارییەکە بلۆک بکات؛ تکایە ڕێگە بە داواکارییەکان بدە بۆ /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'ماڵپەڕەکەت زۆر درەنگ وەڵامی دایەوە. تکایە دواتر دووبارە هەوڵ بدەرەوە، و دڵنیابەرەوە هۆستەکەت زۆر hێواش یان بارگرانی لەسەر نییە.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'ماڵپەڕەکەت وەڵامی دایەوە، بەڵام نەک بەو شێوەیەی چاوەڕوان دەکرا. لەوانەیە REST API لەلایەن پێوەکراوێکی ترەوە دووبارە نووسرابێتەوە، یان ئەو خاڵەی کۆتایی API لە کاش هەڵگیرابێت؛ تکایە /wp-json/babilim/v1/challenge لە کاش و دووبارەنووسینەوە دەربهێنە.','Please check that your site can be reached from the internet, then try again.'=>'تکایە دڵنیابەرەوە ماڵپەڕەکەت لە ئینتەرنێتەوە دەستی پێ دەگات، پاشان دووبارە هەوڵ بدەرەوە.','Re-verify'=>'دووبارە پشتڕاستکردنەوە','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'ئەم ماڵپەڕە لە قەبارەی قبوڵکراوی خزمەتگوزارییەکە بۆ یەک هاوکاتکردن تێپەڕیوە، بۆیە هەندێک بڕگە جێهێڵران: %1$d پێکهاتە و %2$d زمان.','This site is verified.'=>'ئەم ماڵپەڕە پشتڕاستکراوەتەوە.','Registration restarted.'=>'تۆمارکردن دووبارە دەستی پێکردەوە.','Sync complete.'=>'هاوکاتکردن تەواو بوو.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim خەریکی چالاککردن و پشکنینی ئەم ماڵپەڕەیە… ئەم پەڕەیە نوێ بکەرەوە یان چاوەڕێ بکە تا پشکنینی خشتەکراو تەواو دەبێت.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim نەیتوانی چالاککردن تەواو بکات (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'هۆستێک کە تەنها یەک داواکاری PHP لە یەک کاتدا خزمەت دەکات ناتوانێت ئەم هەنگاوە تەواو بکات.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim چالاک کرا: ئەم ماڵپەڕە پشتڕاستکراوەتەوە و %d پێکهاتە دۆزرایەوە.' . "\0" . 'Babilim چالاک کرا: ئەم ماڵپەڕە پشتڕاستکراوەتەوە و %d پێکهاتە دۆزرانەوە.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim ناچالاک کرا. هیچی تر نانێردرێت؛ ئەو وەرگێڕانانەی پێشتر دامەزراون بەردەوام کار دەکەن.','Supplementary translation index rebuilt.'=>'پێرستی وەرگێڕانی تەواوکەر دووبارە دروستکرایەوە.','Sweep complete: %d file deleted.'=>'پشکنین تەواو بوو: %d پەڕگە سڕایەوە.' . "\0" . 'پشکنین تەواو بوو: %d پەڕگە سڕانەوە.','Removed %d installed component.'=>'%d پێکهاتەی دامەزراو لابرا.' . "\0" . '%d پێکهاتەی دامەزراو لابران.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'دامەزراندنە خۆکارەکان ئێستا کوژاونەتەوە؛ ئەگەر دەتەوێت، لە ڕێکخستنەکان دووبارە بیانکەرەوە.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim ئەو پێوەکراو و ڕووکارانەی ئەم ماڵپەڕە دەدۆزێتەوە کە وەرگێڕانیان بۆ زمانەکەت نییە و بۆ هەر یەکێکیان وەرگێڕانێک دادەمەزرێنێت.','Languages found on this site: %s.'=>'ئەو زمانانەی لەم ماڵپەڕەدا دۆزرانەوە: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'وەرگێڕانە بەردەستەکان بە یەک کلیک دادەمەزرێن، و ئەوانەی نین دەتوانرێت داوا بکرێن. دوای ئەوە، وەرگێڕانە نوێیەکان و نوێکردنەوەکان بە خۆکار دادەمەزرێن (لە پلانی بێبەرامبەر، تەنها بۆ ئەو پێوەکراو و ڕووکارانەی پێشتر شوێنێکی بێبەرامبەر بەکاردەهێنن).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'پلانی بێبەرامبەر ژمارەیەکی سنووردار لە پێوەکراو و ڕووکار دەگرێتەوە؛ دوای ئەوەی Babilim چالاک دەکەیت، کۆتای وردی تۆ لە ڕێکخستنەکان پیشان دەدرێت.','What is sent when you enable Babilim'=>'ئەوەی دەنێردرێت کاتێک Babilim چالاک دەکەیت','Enabling…'=>'چالاک دەکرێت…','Enable Babilim'=>'چالاککردنی Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'بە کلیککردن لەسەر چالاککردن، ڕازیت زانیارییە لیستکراوەکانی سەرەوە بنێریت بۆ Babilim.','Check again now'=>'ئێستا دووبارە بپشکنە','Babilim installed %d translation automatically since your last visit.'=>'Babilim لە دوایین سەردانتەوە %d وەرگێڕانی بە خۆکار دامەزراند.' . "\0" . 'Babilim لە دوایین سەردانتەوە %d وەرگێڕانی بە خۆکار دامەزراند.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim خەریکی چالاککردن و پشکنینی ئەم ماڵپەڕەیە… (دوایین هەوڵ: %s)','Check again'=>'دووبارە بپشکنە','No components synced yet.'=>'هێشتا هیچ پێکهاتەیەک هاوکات نەکراوە.','%d succeeded'=>'%d سەرکەوتوو بوو' . "\0" . '%d سەرکەوتوو بوو','%d skipped'=>'%d تێپەڕێنرا' . "\0" . '%d تێپەڕێنرا','%d failed'=>'%d شکستی هێنا' . "\0" . '%d شکستی هێنا','%d not yet tried'=>'%d هێشتا تاقی نەکراوەتەوە' . "\0" . '%d هێشتا تاقی نەکراوەتەوە','Bulk %s:'=>'بەکۆمەڵ %s:','%1$s nothing to do.'=>'%1$s هیچ شتێک نییە بۆ ئەنجامدان.','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'بەردەوامبوون…','Continue next batch (%d left)'=>'بەردەوامبوون لەگەڵ کۆمەڵەی دواتر (%d ماوە)','Search components'=>'گەڕان بەدوای پێکهاتەکان','These are the languages this site uses. You can change them in %s.'=>'ئەمانە ئەو زمانانەن کە ئەم ماڵپەڕە بەکاریان دەهێنێت. دەتوانیت لە %s بیانگۆڕیت.','Upload this component?'=>'ئەم پێکهاتەیە باربکرێت؟','There is no upload waiting for confirmation.'=>'هیچ بارکردنێک چاوەڕێی پشتڕاستکردنەوە نییە.','Back'=>'گەڕانەوە','To translate this component, Babilim needs its source.'=>'بۆ وەرگێڕانی ئەم پێکهاتەیە، Babilim پێویستی بە سەرچاوەکەی هەیە.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'هەموو بوخچەی پلاگین یان ڕووکاری %1$s (وەشانی %2$s) بۆ Babilim بار دەکرێت.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'ئەگەر ئەو بوخچەیە کلیل، تۆمار یان داتای کڕیار لەخۆ بگرێت، ئەوانیش بار دەکرێن. خزمەتگوزارییەکە فایلە هەستیارە باوەکان (ڕێکخستن، ژینگە، پاشەکەوتی بنکەدراو، تۆمار، کلیل) لادەبات، بەڵام گەرەنتی ناکات هەموویان بدۆزێتەوە.','The upload is kept until you ask Babilim to delete it.'=>'بارکراوەکە دەمێنێتەوە تا داوا لە Babilim بکەیت بیسڕێتەوە.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'لەلایەن دابینکەری هۆستی خزمەتگوزارییەکەوە هەڵدەگیرێت و بە مۆدێلی زیرەکی دەستکرد پرۆسێس دەکرێت بۆ دروستکردنی وەرگێڕانەکە.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'دەقی ڕەسەن و ئەو وەرگێڕانانەی لێیەوە دروست کراون دەدرێن بەو ماڵپەڕانەی دیکە کە هەمان وەشان دادەمەزرێنن.','By continuing you confirm that you have the right to upload this component.'=>'بە بەردەوامبوون پشتڕاست دەکەیتەوە کە مافی بارکردنی ئەم پێکهاتەیەت هەیە.','Upload and request'=>'بارکردن و داواکردن','Uploading…'=>'بارکردن…','Cancel'=>'هەڵوەشاندنەوە','Uploading'=>'بارکردن','There is no upload in progress.'=>'هیچ بارکردنێک لە ئارادا نییە.','Uploading part %1$d of %2$d…'=>'بارکردنی بەشی %1$d لە %2$d…','Continue'=>'بەردەوامبوون','Confirm'=>'پشتڕاستکردنەوە','Remove'=>'لابردن','Roll back'=>'گەڕاندنەوە','Nothing to confirm.'=>'هیچ شتێک نییە بۆ پشتڕاستکردنەوە.','Choose a language'=>'زمانێک هەڵبژێرە','Roll back and report'=>'گەڕاندنەوە و ڕاپۆرتکردن','Report a problem'=>'ڕاپۆرتکردنی کێشەیەک','Nothing to choose.'=>'هیچ شتێک نییە بۆ هەڵبژاردن.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. زمانەکە هەڵبژێرە.','Supplementary translations'=>'وەرگێڕانە تەواوکارییەکان','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'بەشداریکردنی تایبەتی هەر پێکهاتەیەک لە پاشکۆی دۆمەینی بنەڕەتیی هاوبەشی هەر ناوچەیەکی زمان.','Component'=>'پێکهاتە','Language'=>'زمان','Included in index'=>'لە پێرستدا لەخۆگیراوە','Entries'=>'تۆمارەکان','Conflicting keys'=>'کلیلە ناکۆکەکان','Yes'=>'بەڵێ','No — component inactive'=>'نەخێر — پێکهاتەکە ناچالاکە','No — installed version differs from the active one'=>'نەخێر — وەشانی دامەزراو جیاوازە لە وەشانی چالاک','No — component removed'=>'نەخێر — پێکهاتەکە لابراوە','No'=>'نەخێر','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'تەنها بەڕێوەبەری تۆڕ دەتوانێت ئەمە ئەنجام بدات، چونکە فایلە وەرگێڕدراوەکان دەگۆڕێت کە لەنێوان هەموو ماڵپەڕەکانی ئەم تۆڕەدا هاوبەشن.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim نەیتوانی دڵنیابوونەوە لەم ماڵپەڕە تەواو بکات (خزمەتگوزارییەکە نەیتوانی پەیوەندی پێوە بکاتەوە). تۆمارکردن ڕاگیراوە.','This site already has an active registration that can no longer be recovered automatically.'=>'ئەم ماڵپەڕە پێشتر تۆمارێکی چالاکی هەیە کە چیتر بە شێوەی خۆکار ناگەڕێندرێتەوە.','Restart registration'=>'دووبارە دەستپێکردنەوەی تۆمارکردن','Babilim settings'=>'ڕێکخستنەکانی Babilim','General'=>'گشتی','Advanced'=>'پێشکەوتوو','Languages'=>'زمانەکان','Automatic installs'=>'دامەزراندنە خۆکارەکان','Install available translations automatically'=>'وەرگێڕانە بەردەستەکان بە شێوەی خۆکار دابمەزرێنە','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'لە پلانی بێبەرامبەردا، تەنها ئەو پێکهاتانە بە شێوەی خۆکار دادەمەزرێن کە پێشتر یەکێک لە شوێنە بێبەرامبەرەکانتیان بەکارهێناوە، بۆیە هیچ شوێنێکی نوێ نابردرێت.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'ئەم ماڵپەڕە بەشێکە لە تۆڕێکی فرەماڵپەڕ، کە وەرگێڕانی نوێ بە شێوەی خۆکار دانامەزرێنێت. ئەو وەرگێڕانانەی پێشتر دامەزراون هێشتا نوێ دەکرێنەوە.','Custom overrides'=>'بەسەرداچوونەوە دەستکردەکان','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'بەسەرداچوونەوە وەرگێڕانەکانی خۆم بپارێزە کاتێک هەموو شتێک پاک دەکرێتەوە یان ئەم پێوەکراوە لادەبرێت.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'ئەو فایلە وەرگێڕانانەی لە %s دایاندەنێیت هەمیشە پێشینەیان هەیە بەسەر ئەوانی Babilim. ئەمانە دەپارێزرێن مەگەر نیشانەکەی لابەریت.','Uninstall'=>'لابردن','Delete all Babilim data on uninstall'=>'سڕینەوەی هەموو داتاکانی Babilim لەکاتی لابردن','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'بە شێوەی بنەڕەتی کوژاوەتەوە: سڕینەوەی پێوەکراوەکە ناسنامەی ئەم ماڵپەڕە دەپارێزێت، بۆ ئەوەی دووبارە دامەزراندنەوە بتوانێت بەکاریبهێنێتەوە.','Account'=>'هەژمار','Save changes'=>'پاشەکەوتکردنی گۆڕانکارییەکان','Disable Babilim'=>'ناچالاککردنی Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'وەرگێڕانە دامەزراوەکان دەپارێزرێن، بەڵام هیچ پشکنین یان داونلۆدێکی دیکە ئەنجام نادرێت.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim ناچالاک دەکەیت؟ وەرگێڕانە دامەزراوەکان دەپارێزرێن، بەڵام هیچ پشکنین یان داونلۆدێکی دیکە ئەنجام نادرێت.','This site is not registered with Babilim yet.'=>'ئەم ماڵپەڕە هێشتا لە Babilim تۆمار نەکراوە.','This site is already licensed. Reload the page.'=>'ئەم ماڵپەڕە پێشتر مۆڵەتی هەیە. پەڕەکە دووبارە باربکەرەوە.','Checkout is not available for this site right now.'=>'پارەدان ئێستا بۆ ئەم ماڵپەڕە بەردەست نییە.','Could not start checkout: %s'=>'نەتوانرا پارەدان دەست پێبکرێت: %s','Babilim is not enabled.'=>'Babilim چالاک نەکراوە.','Not registered yet'=>'هێشتا تۆمار نەکراوە','Not verified'=>'پشتڕاست نەکراوەتەوە','Verified'=>'پشتڕاستکراوەتەوە','Status'=>'دۆخ','Licensed'=>'مۆڵەتدراو','Partner'=>'هاوبەش','Free'=>'بێبەرامبەر','License'=>'مۆڵەت','Upgrade this site'=>'بەرزکردنەوەی ئەم ماڵپەڕە','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'کڕینی یەکجار بۆ ئەم ماڵپەڕە: %1$s %2$s. هەموو نوێکردنەوەکانی وەرگێڕانی داهاتووش لەخۆ دەگرێت. پارەدان لەلایەن Paddle لە تابێکی نوێدا بەڕێوە دەبرێت.','This issues a new restore code and the previous one stops working. Continue?'=>'ئەمە کۆدێکی گێڕانەوەی نوێ دەردەکات و ئەوەی پێشوو کار ناکات. بەردەوام دەبیت؟','Show a new restore code'=>'پیشاندانی کۆدی گێڕانەوەی نوێ','rc_…'=>'rc_…','Restore code'=>'کۆدی گێڕانەوە','Restore purchase'=>'گێڕانەوەی کڕین','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'پێشتر مۆڵەتێکت بۆ ئەم دۆمەینە کڕیوە؟ ئەو کۆدی گێڕانەوەیە بنووسە کە لە کاتی پارەدان وەرتگرتووە.','That does not look like a restore code.'=>'ئەمە وەک کۆدی گێڕانەوە دەرناکەوێت.','This restore code was not recognised for this site.'=>'ئەم کۆدی گێڕانەوەیە بۆ ئەم ماڵپەڕە ناسێنراو نییە.','Too many attempts. Try again tomorrow.'=>'هەوڵی زۆر. سبەی دووبارە تاقی بکەرەوە.','This site must be verified first.'=>'پێویستە سەرەتا ئەم ماڵپەڕە پشتڕاست بکرێتەوە.','Could not restore the purchase: %s'=>'نەتوانرا کڕینەکە بگەڕێنرێتەوە: %s','Purchase restored. This site is now licensed.'=>'کڕینەکە گەڕێندرایەوە. ئێستا ئەم ماڵپەڕە مۆڵەتدارە.','This site has no purchase to show a code for.'=>'ئەم ماڵپەڕە هیچ کڕینێکی نییە کە کۆدی بۆ پیشان بدرێت.','Could not show a new restore code: %s'=>'نەتوانرا کۆدی گێڕانەوەی نوێ پیشان بدرێت: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'کۆدی گێڕانەوەی نوێت: %s. لە شوێنێکی سەلامەت بیپارێزە — کۆدی پێشوو چیتر کار ناکات.','What is sent when Babilim checks this site'=>'ئەوەی دەنێردرێت کاتێک Babilim ئەم ماڵپەڕە دەپشکنێت','(detected)'=>'(دۆزرایەوە)','No language is managed yet.'=>'هێشتا هیچ زمانێک بەڕێوە نابرێت.','Babilim adds translations for every language checked here.'=>'Babilim وەرگێڕان بۆ هەموو ئەو زمانانە زیاد دەکات کە لێرە هەڵبژێردراون.','Add another language'=>'زمانێکی تر زیاد بکە','Choose a language…'=>'زمانێک هەڵبژێرە…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'نەتوانرا لیستی تەواوی ناوچەی زمانی WordPress.org لە خزمەتگوزاریەکە باربکرێت، بۆیە ئێستا نەتوانرێت زمانێکی تر زیاد بکرێت.','Theme'=>'ڕووکار','Plugin'=>'پێوەکراو','Free quota'=>'کۆتای بێبەرامبەر','Downloads: %1$d/%2$d (%3$s)'=>'داگرتنەکان: %1$d/%2$d (%3$s)','Supplementary translation index'=>'پێرستی وەرگێڕانی تەواوکەر','Built'=>'دروستکراو','Included'=>'لەخۆگیراو','Excluded'=>'دەرهێنراو','Already in WordPress core'=>'پێشتر لە ناوکی WordPress دایە','Supplementary translation maintenance'=>'چاکسازی وەرگێڕانی تەواوکەر','Maintenance status is not available right now.'=>'دۆخی چاکسازی لە ئێستادا بەردەست نییە.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'پاکسازییەک لە %1$s ڕاگیرا: %2$s. هیچ شتێک نەسڕایەوە.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'دوایین پاکسازی لە %1$s: %2$d نوێ نیشانکراون، %3$d پەڕگە سڕانەوە، %4$d تۆمار لابران.','No cleanup has run yet.'=>'هێشتا هیچ پاکسازییەک ئەنجام نەدراوە.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'نووسینێکی پێرستی وەرگێڕان لە %1$s (%2$s) لەگەڵ داواکارییەکی تر ناکۆک بوو و جێبەجێ نەکرا؛ نوێترین وەشان هێڵرایەوە.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'نووسینێک لە پێرستی وەرگێڕان لە %1$s (%2$s) تەواو نەکرا و جێبەجێ نەکرا (%3$s).','Maintenance'=>'چاککردنەوە و پارێزگاری','Rebuild index now'=>'ئێستا پێرست بنیاتبنێرەوە','Sweep now'=>'ئێستا پاکی بکەرەوە','Danger zone'=>'ناوچەی مەترسی','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'هەموو پەڕگەی زمانێک دەسڕێتەوە کە Babilim بۆ هەموو پێوەکراوەکان و ڕووکارەکانی ئەم ماڵپەڕە دایمەزراندووە.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'هەموو ئەوەی Babilim دایمەزراندووە لاببرێت؟ ئەمە هەموو پەڕگەی زمانێک دەسڕێتەوە کە Babilim بۆ هەموو پێوەکراوەکان و ڕووکارەکانی ئەم ماڵپەڕە دایمەزراندووە.','Remove everything Babilim installed'=>'هەموو ئەوەی Babilim دایمەزراندووە لاببە','This string is too long to be sent as a report, so no report form is offered for it.'=>'ئەم دەقە زۆر درێژە بۆ ئەوەی وەک ڕاپۆرت بنێردرێت، بۆیە فۆرمی ڕاپۆرت بۆی پێشکەش ناکرێت.','Category'=>'هاوپۆل','Choose a category…'=>'هاوپۆلێک هەڵبژێرە…','Roll back and send report'=>'گەڕاندنەوە و ناردنی ڕاپۆرت','Send report'=>'ناردنی ڕاپۆرت','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'بەشێک لە دەقی ئەم پێکهاتەیە لەلایەن دروستکەرەکەیەوە بە کۆد نووسراوە و پاکێجی زمان ناتوانێت وەریبگێڕێت.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'لەگەڵ ڕووکارەکەدا هاتووە','Bundled with the plugin'=>'لەگەڵ پێوەکراوەکەدا هاتووە','Upload was not accepted'=>'بارکردنەکە قبوڵ نەکرا','Upload expired before it finished'=>'بارکردنەکە پێش تەواوبوون بەسەرچوو','No translation'=>'هیچ وەرگێڕانێک نییە','Upload in progress — continue or cancel'=>'بارکردن بەردەوامە — بەردەوام بە یان هەڵیبوەشێنەوە','Scheduled, waiting to be processed'=>'مەوعیدی بۆ دانراوە، چاوەڕێی جێبەجێکردنە','Translating…'=>'وەرگێڕان بەڕێوەیە…','Translation failed'=>'وەرگێڕان شکستی هێنا','Free quota used'=>'کۆتای بێبەرامبەر بەکارهات','Needs a paid license'=>'مۆڵەتی پارەدراوی پێویستە','Not supported'=>'پشتگیری ناکرێت','Status unknown'=>'دۆخ نەزانراوە','translation statusInstalled'=>'دامەزراوە','Update available'=>'بەڕۆژکردنەوە بەردەستە','Removed after a failed integrity check'=>'دوای شکستی پشکنینی تەواوی لابرا','Installed · built for %s, new version scheduled'=>'دامەزراوە · بۆ %s دروستکراوە، وەشانی نوێ مەوعیدی بۆ دانراوە','Installed · built for a different version, new version scheduled'=>'دامەزراوە · بۆ وەشانێکی جیاواز دروستکراوە، وەشانی نوێ مەوعیدی بۆ دانراوە','Installed · built for %s, translating the new version…'=>'دامەزراوە · بۆ %s دروستکراوە، وەشانی نوێ وەردەگێڕدرێت…','Installed · built for a different version, translating the new version…'=>'دامەزراوە · بۆ وەشانێکی جیاواز دروستکراوە، وەشانی نوێ وەردەگێڕدرێت…','Installed · built for %1$s, this site has %2$s'=>'دامەزراوە · بۆ %1$s دروستکراوە، ئەم ماڵپەڕە %2$sی هەیە','Installed · built for %s'=>'دامەزراوە · بۆ %s دروستکراوە','Installed · built for a different version'=>'دامەزراوە · بۆ وەشانێکی جیاواز دروستکراوە','Installed · built for %s, new version failed'=>'دامەزراوە · بۆ %s دروستکراوە، وەشانی نوێ سەرکەوتوو نەبوو','Installed · built for a different version, new version failed'=>'دامەزراوە · بۆ وەشانێکی جیاواز دروستکراوە، وەشانی نوێ سەرکەوتوو نەبوو','Installed · built for %s, new version needs a paid license'=>'دامەزراوە · بۆ %s دروستکراوە، وەشانی نوێ مۆڵەتی پارەدراوی پێویستە','Installed · built for a different version, new version needs a paid license'=>'دامەزراوە · بۆ وەشانێکی جیاواز دروستکراوە، وەشانی نوێ مۆڵەتی پارەدراوی پێویستە','Installed · built for %s, free quota used'=>'دامەزراوە · بۆ %s دروستکراوە، کۆتای بێبەرامبەر بەکارهاتووە','Installed · built for a different version, free quota used'=>'دامەزراوە · بۆ وەشانێکی جیاواز دروستکراوە، کۆتای بێبەرامبەر بەکارهاتووە','translation statusAvailable'=>'بەردەست','Installed · %s'=>'دامەزراوە · %s','Available · %s'=>'بەردەست · %s','Update'=>'بەڕۆژکردنەوە','Download'=>'داگرتن','Updating…'=>'بەڕۆژدەکرێتەوە…','Downloading…'=>'دادەگیرێت…','Retry request'=>'دووبارە داواکردنەوە','Request newer translation'=>'داواکردنی وەرگێڕانی نوێتر','Request translation'=>'داواکردنی وەرگێڕان','Requesting…'=>'داوا دەکرێت…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'داواکردنی وەرگێڕان یەکێک لە شوێنە بێبەرامبەرەکانت بەکاردەهێنێت، مەگەر ئەم پێکهاتەیە پێشتر یەکێکی بەکارهێنابێت. وەرگێڕانی شکستخواردوو شوێنەکە ناگەڕێنێتەوە.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'ئەگەر ئەم پێکهاتەیە هێشتا یەکێک لە شوێنە بێبەرامبەرەکانت بەکارنەهێنابێت، داواکردنی وەرگێڕان یەکێکیان بەکاردەهێنێت. وەرگێڕانی شکستخواردوو شوێنەکە ناگەڕێنێتەوە. بەردەوام دەبیت؟','No plugins or themes found.'=>'هیچ پێوەکراوێک یان ڕووکارێک نەدۆزرایەوە.','Clear filters'=>'پاککردنەوەی پاڵاوتنەکان','No components match these filters. %s'=>'هیچ پێکهاتەیەک لەگەڵ ئەم پاڵاوتنانە نایەتەوە. %s','Select all'=>'هەڵبژاردنی هەموو','All'=>'هەموو','Available'=>'بەردەست','Updates'=>'بەڕۆژکردنەوەکان','Requestable'=>'شیاوی داواکردن','Installed'=>'دامەزراوە','Plugins'=>'پێوەکراوەکان','Themes'=>'ڕووکارەکان','All languages'=>'هەموو زمانەکان','%d to install'=>'%d بۆ دامەزراندن' . "\0" . '%d بۆ دامەزراندن','Language:'=>'زمان:','Bulk actions apply to every matching language of each selected component.'=>'کرداری بەکۆمەڵ بۆ هەموو زمانە گونجاوەکانی هەر پێکهاتەیەکی هەڵبژێردراو جێبەجێ دەکرێت.','Bulk actions apply only to the selected language of each selected component.'=>'کرداری بەکۆمەڵ تەنها بۆ زمانی هەڵبژێردراوی هەر پێکهاتەیەکی هەڵبژێردراو جێبەجێ دەکرێت.','Version %s'=>'وەشانی %s','Theme · %s'=>'ڕووکار · %s','Plugin · %s'=>'پێوەکراو · %s','Remove the %2$s translation of %1$s from this site?'=>'وەرگێڕانی %2$sی %1$s لەم ماڵپەڕە لاببرێت؟','Roll back the %2$s translation of %1$s to the previous build?'=>'وەرگێڕانی %2$sی %1$s بگەڕێنرێتەوە بۆ بیلدی پێشوو؟','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'ئاڵنگاریی تۆمارکردن بە شێوەی چاوەڕوانکراو نییە.','That is not a valid build identifier.'=>'ئەمە ناسێنەری بیلدێکی دروست نییە.','Refusing to write outside the Babilim language-file directory.'=>'نووسین لە دەرەوەی بوخچەی پەڕگەکانی زمانی Babilim ڕەتکرایەوە.','Could not write the downloaded package to disk.'=>'نەتوانرا pakێجی داگیراو لەسەر دیسک بنووسرێت.','Unexpected HTTP %d response.'=>'وەڵامی HTTP %d چاوەڕوانکراو نەبوو.','This site\'s URL, so the service can verify you own it.'=>'نیشانی ماڵپەڕی ئەم ماڵپەڕە، بۆ ئەوەی خزمەتگوزارییەکە بتوانێت دڵنیا ببێتەوە کە تۆ خاوەنیتی.','Your WordPress version, to serve compatible translation files.'=>'وەشانی WordPressـەکەت، بۆ پێشکەشکردنی پەڕگەی وەرگێڕانی گونجاو.','Your PHP version, for compatibility.'=>'وەشانی PHPـەکەت، بۆ گونجاوی.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'وەشانی خودی ئەم پێوەکراوە، بۆ ئەوەی خزمەتگوزارییەکە بتوانێت پێت بڵێت بەڕۆژی بکەیتەوە ئەگەر زۆر کۆن بوو بۆ پەیوەندیکردن.','This site\'s configured locale.'=>'ناوچەی زمانی ڕێکخراوی ئەم ماڵپەڕە.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'هەموو ناوچەیەکی زمان کە لەم ماڵپەڕەدا بەکاردێت (ناوچەی زمانی ماڵپەڕ، پاکێجە زمانە دامەزراوەکان، ناوچەی زمانی بەکارهێنەران، و هەرچییەک بە دەستی زیادی دەکەیت). هیچ ناوچەیەکی زمان بە جیاواز مامەڵەی لەگەڵ ناکرێت.','(a public key generated for this site)'=>'(کلیلێکی گشتی کە بۆ ئەم ماڵپەڕە دروستکراوە)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'کلیلی گشتیی دامەزراندنی ئەم ماڵپەڕە، بۆ سەلماندنی ئەوەی داواکارییەکان بەڕاستی لەم ماڵپەڕەوە دێن. تەنها نیوە گشتییەکەی دەنێردرێت.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'هەموو پێوەکراو/ڕووکارێکی دامەزراو: slugەکەی، وەشانەکەی، دۆمەینەکانی دەقەکەی، ئایا لە WordPress.org لیست کراوە، ئەو ناوچە زمانییانەی لەگەڵ خۆیدا دابین کراون، و ئەو ناوچە زمانییانەی کە پێشتر وەرگێڕانی Babilimت بۆ دامەزراندوون.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'تەنها کاتێک بارکردنێک پشتڕاست دەکەیتەوە بۆ پێوەکراو یان ڕووکارێک کە لەسەر WordPress.org نییە: هەموو بوخچەی ئەو پێکهاتەیە، وەک zip.','(generic codes and coordinates only)'=>'(تەنها کۆد و کۆئۆردینەیتی گشتی)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'تا ٢٠ ڕووداوی دیاگنۆستیکی کە لە چاوەڕوانیدان (بۆ نموونە پەڕگەیەک کە لە پشکنینی تەواویدا سەرکەوتوو نەبووە)، هەریەکەیان تەنها کۆدێک، پێکهاتەیەک و ناوچەیەکی زمان لەخۆ دەگرێت، و هەرگیز هیچ ناوەڕۆکی دەق یان دەقی وەرگێڕدراو لەخۆ ناگرێت.','Unsafe locale: %s'=>'ناوچەی زمانی ناسەلامەت: %s','Manifest unavailable: %s'=>'مانیفێست بەردەست نییە: %s','Could not determine active components; the existing merged index was left unchanged.'=>'نەتوانرا پێکهاتە چالاکەکان دیاری بکرێن؛ ئیندێکسی تێکەڵکراوی بەردەست بێ گۆڕان ماوەتەوە.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'نەتوانرا پێوەکراو/ڕووکارە دامەزراوەکان دیاری بکرێن؛ پاکسازی پەڕێنرا و هیچ شتێک نەسڕایەوە.','Sweep aborted without orphaning anything: %s.'=>'پاکسازی بێ ئەوەی هیچ شتێک بێ خاوەن بکات ڕاگیرا: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'پاکسازییەکە جێبەجێ کرا، بەڵام هەندێک لە گۆڕانکارییەکانی نەتوانرا لە ئیندێکسی وەرگێڕان تۆمار بکرێن؛ پاکسازی داهاتوو دووبارە هەوڵیان دەداتەوە.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'ئیندێکسی تێکەڵکراو بۆ \'%s\' دووبارە دروستکرایەوە، بەڵام ئیندێکسی وەرگێڕان نەیتوانی تۆماری بکات؛ دروستکردنەوەی داهاتوو دووبارە هەوڵ دەداتەوە.','Could not write the staged merged index.'=>'نەتوانرا ئیندێکسی تێکەڵکراوی ئامادەکراو بنووسرێت.','Re-parsed entry count did not match the built index.'=>'ژمارەی تۆمارە دووبارە شیکراوەکان لەگەڵ ئیندێکسی دروستکراو یەک نەگرتەوە.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'نەتوانرا ئیندێکسی تێکەڵکراو بۆ \'%s\' بخرێتە شوێنی خۆی؛ ئیندێکسی پێشووی بەکارهاتوو (ئەگەر هەبوو) سڕایەوە نەک نیوەبەڕۆژکراو بمێنێتەوە. هیچ زیادکراوێکی دۆمەینی default بۆ ئەم ناوچەی زمانە پێشکەش ناکرێت تا دروستکردنەوەی سەرکەوتووی داهاتوو.','Could not open zip: %s'=>'نەتوانرا zip بکرێتەوە: %s','Zip has no manifest.json.'=>'zip هیچ manifest.jsonـێکی تێدا نییە.','manifest.json in the zip is not valid JSON.'=>'manifest.json لە zip دا JSONی دروست نییە.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\'ـی manifest.json لەگەڵ بەهای چاوەڕوانکراو یەک ناگرێتەوە.','Another installation is running; try again in a moment.'=>'دامەزراندنێکی تر بەڕێوەدەچێت؛ دوای ساتێک دووبارە هەوڵ بدەرەوە.','Not a valid server_build_id: %s'=>'server_build_idی دروست نییە: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'جۆری مانیفێستی پاکێج \'%1$s\' لەگەڵ جۆری داواکراو \'%2$s\' یەک ناگرێتەوە.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'دۆمەینی دەقی پاکێج \'%1$s\' لەگەڵ کۆپیی ئەم ماڵپەڕە لە پێکهاتەکە (\'%2$s\') یەک ناگرێتەوە، بۆیە دانەمەزرا.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'دۆمەینی دیاریکراو \'%1$s\' نە لەگەڵ slugی خودی مانیفێستی پاکێج \'%2$s\' و نە لەگەڵ text_domainـەکەی \'%3$s\' یەک دەگرێتەوە.','Unsafe slug: %s'=>'slugی ناپارێزراو: %s','Unsafe text_domain: %s'=>'text_domainی ناپارێزراو: %s','The package has no %s for its own text domain.'=>'بۆ دۆمەینی دەقی خۆی، پاکێجەکە %sی نییە.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json بوونی نییە یان \'%s\'ی نادروستی تێدایە.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json بوونی نییە یان \'entries\'ی نادروستی تێدایە.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json بوونی نییە یان \'files\'ی نادروستی تێدایە.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json بوونی نییە یان \'extra_domains\'ی نادروستی تێدایە.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json بوونی نییە یان \'build_no\'ی نادروستی تێدایە.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\'ی manifest.json ناسنامەیەکی بیلدی دروست نییە.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\'ی manifest.json دەقی وەشانێکی دروست نییە.','manifest.json\'s \'status\' must be \'published\'.'=>'دۆخی manifest.json دەبێت \'published\' بێت.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'جۆری manifest.json دەبێت \'plugin\' یان ڕووکار (theme) بێت.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json \'default_domain_entries\'ی نادروستی تێدایە.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json \'default_domain_files\'ی نادروستی تێدایە.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest بوونی نییە یان \'%s\'ی نادروستی تێدایە.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\'ی expected_manifest ناسنامەیەکی بیلدی دروست نییە.','No record for %s'=>'تۆمار نییە بۆ %s','One or more served files no longer match the manifest.'=>'یەک یان چەند پەڕگەی خزمەتکراو چیتر لەگەڵ manifest ناگونجێن.','No previous build to roll back to.'=>'هیچ بیلدێکی پێشوو نییە بۆ گەڕاندنەوە.','The change could not be recorded in the translation index; please try again.'=>'گۆڕانکارییەکە لە پێڕستی وەرگێڕان تۆمار نەکرا؛ تکایە دووبارە هەوڵبدەرەوە.','Unknown kind: %s'=>'جۆری نەناسراو: %s','Unsafe domain: %s'=>'دۆمەینی نایمن: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'دۆمەینی دەقی \'%1$s\' (%2$s) پێشتر بۆ پێکهاتەیەکی دامەزراوی تر خزمەت دەکرێت (%3$s)؛ هیچ شتێک دانەمەزرا.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'گەڕاندنەوە \'%1$s\' (%2$s) دەنووسێتەوە، کە ئێستا بۆ پێکهاتەیەکی دامەزراوی تر خزمەت دەکرێت (%3$s)؛ هیچ شتێک نەگۆڕدرا.','Zip is missing expected file: %s'=>'پەڕگەی چاوەڕوانکراو لە zip نییە: %s','sha256 mismatch for %s'=>'ناکۆکی sha256 بۆ %s','The package declares no main translation file.'=>'پاکێجەکە هیچ پەڕگەیەکی سەرەکی وەرگێڕانی ڕانەگەیاندووە.','Zip is missing expected default file: %s'=>'پەڕگەی بنەڕەتی چاوەڕوانکراو لە zip نییە: %s','sha256 mismatch for default/%s'=>'ناکۆکی sha256 بۆ default/%s','Could not stage %s'=>'نەتوانرا %s ئامادە بکرێت','Could not stage default/%s'=>'نەتوانرا default/%s ئامادە بکرێت','Entry count mismatch for %s'=>'ژمارەی تۆمارەکان یەک ناگرنەوە بۆ %s','Could not verify entry count for %s'=>'نەتوانرا ژمارەی تۆمارەکان بپشکنرێت بۆ %s','l10n.php entry count mismatch for %s'=>'ژمارەی تۆمارەکانی l10n.php یەک ناگرنەوە بۆ %s','Default supplement entry count mismatch.'=>'ژمارەی تۆمارەکانی تەواوکەری بنەڕەتی یەک ناگرنەوە.','The package produced no servable main translation file.'=>'پاکێجەکە هیچ پەڕگەیەکی سەرەکی وەرگێڕانی بەرهەم نەهێنا کە بتوانرێت پێشکەش بکرێت.','Could not prepare %s for rollback.'=>'نەتوانرا %s بۆ گەڕاندنەوە ئامادە بکرێت.','Could not back up %s before replacing it.'=>'نەتوانرا پێش گۆڕینی %s یەدەگ بکرێت.','Could not move %s into place.'=>'نەتوانرا %s بخرێتە شوێنی خۆی.','English (United States)'=>'ئینگلیزی (ویلایەتە یەکگرتووەکان)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest بەردەست نییە: %s','could not read _manifest.json: %s'=>'نەتوانرا _manifest.json بخوێندرێتەوە: %s','failed to parse _manifest.json: %s'=>'شکستی هێنا لە شیکردنەوەی _manifest.json: %s','_manifest.json has an unexpected structure'=>'_manifest.json پێکهاتەیەکی چاوەڕواننەکراوی هەیە','Could not create the package archive.'=>'نەتوانرا پەڕگەی کۆکراوەی پاکێج دروست بکرێت.','No writable temporary directory is available for packaging.'=>'هیچ بوخچەیەکی کاتی کە بتوانرێت تێیدا بنووسرێت بۆ پاکێجکردن بەردەست نییە.','A file in the component could not be read, so it was not packaged.'=>'پەڕگەیەک لە پێکهاتەکەدا نەخوێنرایەوە، بۆیە پاکێج نەکرا.','Only plugins and themes can be packaged.'=>'تەنها پێوەکراوەکان و ڕووکارەکان دەکرێن پاکێج بکرێن.','The component\'s main file was not found.'=>'پەڕگەی سەرەکیی پێکهاتەکە نەدۆزرایەوە.','The component is not inside the plugins or themes directory.'=>'پێکهاتەکە لە بوخچەی پێوەکراوەکان یان ڕووکارەکاندا نییە.','Babilim ran out of time for this step and will continue on the next check.'=>'کاتی Babilim بۆ ئەم هەنگاوە تەواو بوو و لە پشکنینی داهاتوودا بەردەوام دەبێت.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim نەیتوانی ئەم ماڵپەڕە پشتڕاست بکاتەوە، بۆیە هیچ شتێک دابەزێنراو یان دامەزراو نابێت تا پشتڕاستکردنەوە سەرکەوتوو دەبێت.','Registration response was missing required fields.'=>'وەڵامی تۆمارکردن خانە پێویستەکانی تێدا نەبوو.','No pending challenge to verify.'=>'هیچ تەحەددایەکی چاوەڕوان بۆ پشتڕاستکردنەوە نییە.','Verify response was missing site_token.'=>'وەڵامی پشتڕاستکردنەوە site_token ی تێدا نەبوو.','No site id is on file to rotate a token for.'=>'هیچ ناسنامەیەکی ماڵپەڕی تۆمارکراو نییە بۆ ئەوەی تۆکنێکی بۆ بگۆڕدرێت.','Rotate-token response was missing site_token.'=>'وەڵامی گۆڕینی تۆکن site_token ی تێدا نەبوو.','nonce must be a hexadecimal string.'=>'nonce دەبێت دەقێکی هێکسادیسیماڵ بێت.','No pending challenge for this nonce.'=>'هیچ تەحەددایەکی چاوەڕوان بۆ ئەم nonce یە نییە.','Too many requests.'=>'داواکاری زۆرە.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'ئەم ماڵپەڕە %1$d پێکهاتەی لە %2$d زماندا هەیە، کە پێویستی بە %3$d کۆمەڵەی پشکنین هەیە؛ Babilim لە هەر جارێکدا زیاترین %4$d دەتوانێت بەڕێوە ببات. زمانە بەڕێوەبراوەکان لە ڕێکخستنەکان کەم بکەرەوە یان پێوەکراو و ڕووکارە بەکارنەهاتووەکان ناچالاک بکە، پاشان ئێستا دووبارە پشکنین دابگرە.','Babilim could not finish checking this site.'=>'Babilim نەیتوانی پشکنینی ئەم ماڵپەڕە تەواو بکات.','This site\'s address is too long for Babilim to register.'=>'ناونیشانی ئەم ماڵپەڕە درێژتر لەوەیە Babilim تۆماری بکات.','This site\'s locale code is not one Babilim can register.'=>'کۆدی ناوچەی زمانی ئەم ماڵپەڕە ئەو کۆدە نییە کە Babilim بتوانێت تۆماری بکات.','The download response was missing a usable location.'=>'وەڵامی داگرتن شوێنێکی گونجاو بۆ بەکارهێنانی تێدا نەبوو.','The service\'s upload offer was incomplete.'=>'پێشنیاری بارکردنی خزمەتگوزارییەکە تەواو نەبوو.','This component is larger than the service accepts, so it cannot be uploaded.'=>'ئەم پێکهاتەیە لەو قەبارەیە گەورەترە کە خزمەتگوزارییەکە وەریدەگرێت، بۆیە ناتوانرێت بار بکرێت.','The packaged component could not be read.'=>'پێکهاتە پاکێجکراوەکە نەخوێنرایەوە.','A part of the upload kept failing, so the upload was cancelled.'=>'بەشێک لە بارکردنەکە بەردەوام شکستی هێنا، بۆیە بارکردنەکە هەڵوەشێنرایەوە.','Could not read: %s'=>'نەخوێنرایەوە: %s']];